	private class ProgramNodeUpdateListener : ArchiveRootNodeListener {

		/* @Override */
		public void archiveNodeAdded(DataTypeStoreNode node) {
			if (node is ProgramArchiveNode programNode) {
				restoreProgramTreeState(programNode);
			}
		}

		/* @Override */
		public void archiveNodeRemoved(DataTypeStoreNode node) {
			if (node is ProgramArchiveNode programNode) {
				saveProgramTreeState(programNode);
			}
		}
	}


	internal class _Anon_GMouseListenerAdapter_1 : GMouseListenerAdapter
	{


			private GTreeNode lastClickedNode;

			/* @Override */
			public void doubleClickTriggered(MouseEvent e) {

				Point point = e.getPoint();
				GTreeNode clickedNode = archiveGTree.getNodeForLocation(point.x, point.y);
				if (clickedNode == null) {
					return;
				}

				if (clickedNode != lastClickedNode) {
					// this can happen when the tree moves during a double-click
					return;
				}

				if (clickedNode is DataTypeNode dtNode) {
					DataType dt = dtNode.getDataType();
					plugin.edit(dt);
				}
			}

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				base.mouseClicked(e);
				Point point = e.getPoint();
				GTreeNode clickedNode = archiveGTree.getNodeForLocation(point.x, point.y);
				lastClickedNode = clickedNode;
			}
		
	}


